import{_ as e,c as t,o as r,a2 as o}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Backend","description":"","frontmatter":{"sidebarPos":5,"sidebarTitle":"Backend"},"headers":[],"relativePath":"system-reference/backend/overview.md","filePath":"system-reference/backend/overview.md","lastUpdated":1778363927000}'),a={name:"system-reference/backend/overview.md"},d=o(`<h1 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h1><p>Reference for every PHP layer that ships with Modularous. Sections below are ordered alphabetically — each one points at the directory under <code>src/</code> it documents and the matching reference page under <code>system-reference/backend/</code>.</p><table><thead><tr><th>Section</th><th>Source path</th><th>Reference</th></tr></thead><tbody><tr><td><a href="#activators">Activators</a></td><td><code>src/Activators/</code></td><td><a href="/system-reference/backend/activators/overview">Activators →</a></td></tr><tr><td><a href="#brokers">Brokers</a></td><td><code>src/Brokers/</code></td><td><a href="/system-reference/backend/brokers/overview">Brokers →</a></td></tr><tr><td><a href="#console-commands">Console Commands</a></td><td><code>src/Console/</code></td><td><a href="/guide/console/overview">Console guide →</a></td></tr><tr><td><a href="#controllers">Controllers</a></td><td><code>src/Http/Controllers/</code></td><td><a href="/system-reference/backend/http/controllers/overview">Controllers →</a></td></tr><tr><td><a href="#entities">Entities</a></td><td><code>src/Entities/</code></td><td><a href="/system-reference/backend/entities/overview">Entities →</a></td></tr><tr><td><a href="#entity-traits">Entity Traits</a></td><td><code>src/Entities/Traits/</code></td><td><a href="/system-reference/backend/entity-traits/overview">Entity Traits →</a></td></tr><tr><td><a href="#events-listeners">Events &amp; Listeners</a></td><td><code>src/Events/</code>, <code>src/Listeners/</code></td><td><a href="/system-reference/backend/events/overview">Events &amp; Listeners →</a></td></tr><tr><td><a href="#facades">Facades</a></td><td><code>src/Facades/</code></td><td><a href="/system-reference/backend/facades/overview">Facades →</a></td></tr><tr><td><a href="#form-requests">Form Requests</a></td><td><code>src/Http/Requests/</code></td><td><a href="/system-reference/backend/http/request/overview">Form Requests →</a></td></tr><tr><td><a href="#generators">Generators</a></td><td><code>src/Generators/</code></td><td><a href="/system-reference/backend/generators/overview">Generators →</a></td></tr><tr><td><a href="#helpers">Helpers</a></td><td><code>src/Helpers/</code></td><td><a href="/system-reference/backend/helpers/overview">Helpers →</a></td></tr><tr><td><a href="#middleware">Middleware</a></td><td><code>src/Http/Middleware/</code></td><td><a href="/system-reference/backend/http/middleware/overview">Middleware →</a></td></tr><tr><td><a href="#notifications">Notifications</a></td><td><code>src/Notifications/</code></td><td><a href="/system-reference/backend/notifications/overview">Notifications →</a></td></tr><tr><td><a href="#providers">Providers</a></td><td><code>src/Providers/</code></td><td><a href="/system-reference/backend/providers/overview">Providers →</a></td></tr><tr><td><a href="#repository-traits">Repository Traits</a></td><td><code>src/Repositories/Traits/</code></td><td><a href="/system-reference/backend/repository-traits/overview">Repository Traits →</a></td></tr><tr><td><a href="#scheduled-jobs">Scheduled Jobs</a></td><td><code>src/Schedulers/</code></td><td><a href="/system-reference/backend/scheduled-jobs/overview">Scheduled Jobs →</a></td></tr><tr><td><a href="#services">Services</a></td><td><code>src/Services/</code></td><td><a href="/system-reference/backend/services/overview">Services →</a></td></tr><tr><td><a href="#support">Support</a></td><td><code>src/Support/</code></td><td><a href="/system-reference/backend/support/overview">Support →</a></td></tr><tr><td><a href="#view-composers">View Composers</a></td><td><code>src/Http/ViewComposers/</code></td><td><a href="/system-reference/backend/http/view-composers/overview">View Composers →</a></td></tr></tbody></table><hr><h2 id="architecture-at-a-glance" tabindex="-1">Architecture at a glance <a class="header-anchor" href="#architecture-at-a-glance" aria-label="Permalink to &quot;Architecture at a glance&quot;">​</a></h2><p>Modularous layers a Laravel package on top of <code>nWidart/laravel-modules</code> and adds a CRUD-aware admin pipeline that every module inherits. The backend is organised as a stack of composable layers — bootstrap on top, persistence at the bottom — with cross-cutting services sitting alongside.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Bootstrap        Providers · Activators · Facades · Helpers     │</span></span>
<span class="line"><span>│                   ──────────────────────────────────────────────  │</span></span>
<span class="line"><span>│  HTTP entry       Middleware → Form Requests → Controllers       │</span></span>
<span class="line"><span>│                   ──────────────────────────────────────────────  │</span></span>
<span class="line"><span>│  Domain           Repositories ↔ Repository Traits               │</span></span>
<span class="line"><span>│                   Entities ↔ Entity Traits                       │</span></span>
<span class="line"><span>│                   ──────────────────────────────────────────────  │</span></span>
<span class="line"><span>│  Reactions        Events → Listeners → Notifications             │</span></span>
<span class="line"><span>│                   ──────────────────────────────────────────────  │</span></span>
<span class="line"><span>│  Background       Scheduled Jobs · Console Commands              │</span></span>
<span class="line"><span>│                   ──────────────────────────────────────────────  │</span></span>
<span class="line"><span>│  Cross-cutting    Services · Support · View Composers · Brokers  │</span></span>
<span class="line"><span>│                   Generators (build-time only)                   │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="typical-request-lifecycle" tabindex="-1">Typical request lifecycle <a class="header-anchor" href="#typical-request-lifecycle" aria-label="Permalink to &quot;Typical request lifecycle&quot;">​</a></h3><p>A normal admin CRUD request walks through most of these layers in order:</p><ol><li><strong>Providers</strong> — <code>ModularousProvider</code> boots child providers (<code>BaseServiceProvider</code>, <code>RouteServiceProvider</code>, <code>AuthServiceProvider</code>, …) and binds every container entry the rest of the stack depends on.</li><li><strong>Activators</strong> — <code>ModularousActivator</code> and <code>ModuleActivator</code> short-circuit the request if the target module or route is disabled.</li><li><strong>Middleware</strong> — the <code>web</code> / <code>admin</code> / <code>api</code> pipelines run guards (<code>Authenticate</code>, <code>Authorization</code>, <code>Hostable</code>, <code>Language</code>, <code>Navigation</code>, <code>HandleInertiaRequests</code>, …).</li><li><strong>Form Request</strong> — a <code>BaseFormRequest</code> subclass authorizes the user and validates input before the controller method runs.</li><li><strong>Controller</strong> — <code>BaseController</code> resolves the active route, applies traits (<code>ManageIndexAjax</code>, <code>ManageInertia</code>, <code>ManagePrevious</code>, <code>ManageSingleton</code>, <code>ManageTranslations</code>), renders the form schema, and delegates persistence to <code>$this-&gt;repository</code>.</li><li><strong>Repository (+ Traits)</strong> — the base <code>Repository</code> invokes every applicable <a href="#repository-traits">repository trait</a> (<code>prepareFieldsBeforeSave{Trait}</code>, <code>afterSave{Trait}</code>, …) around the Eloquent <code>save()</code>.</li><li><strong>Entity (+ Traits)</strong> — Eloquent models compose <a href="#entity-traits">entity traits</a> for slugs, positions, soft-delete, translations, media, files, repeaters, blocks, processes, state, payments, presenters, and broadcasting context.</li><li><strong>Events &amp; Listeners</strong> — model lifecycle and auth events fire; <code>Listener::handle()</code> resolves the matching <code>{EventName}Notification</code> and dispatches it when <code>modularous.mail.enabled = true</code>.</li><li><strong>View Composers</strong> — for Inertia/Blade responses, composers inject shared props (current user, navigation, uploader configs, localization, URLs).</li><li><strong>Response</strong> — Inertia/JSON/Blade payload returns to the client; broadcasted events propagate over Echo channels.</li></ol><h3 id="how-the-layers-reference-each-other" tabindex="-1">How the layers reference each other <a class="header-anchor" href="#how-the-layers-reference-each-other" aria-label="Permalink to &quot;How the layers reference each other&quot;">​</a></h3><table><thead><tr><th>If you are working on…</th><th>You typically touch…</th></tr></thead><tbody><tr><td>A new admin route</td><td><a href="#providers">Providers</a> → <a href="#generators">Generators</a> → <a href="#controllers">Controllers</a> → <a href="#form-requests">Form Requests</a> → <a href="#entities">Entities</a> → <a href="#repository-traits">Repository Traits</a></td></tr><tr><td>Authentication / registration</td><td><a href="#middleware">Middleware</a> → <a href="#controllers">Controllers</a> (Auth) → <a href="#brokers">Brokers</a> → <a href="#notifications">Notifications</a> → <a href="#events-listeners">Events &amp; Listeners</a></td></tr><tr><td>Caching / invalidation</td><td><a href="#services">Services</a> (<code>ModularousCacheService</code>, <code>CacheRelationshipGraph</code>) → <a href="#repository-traits">Repository Traits</a> (Logic) → <a href="#console-commands">Console Commands</a> (<code>cache:*</code>)</td></tr><tr><td>File / media uploads</td><td><a href="#controllers">Controllers</a> (Filepond / FileLibrary / MediaLibrary) → <a href="#form-requests">Form Requests</a> → <a href="#services">Services</a> (FilepondManager, FileLibrary, MediaLibrary, Uploader) → <a href="#entity-traits">Entity Traits</a> (HasFileponds, HasFiles, HasImages)</td></tr><tr><td>Multi-tenant routing</td><td><a href="#providers">Providers</a> (<code>RouteServiceProvider</code>) → <a href="#support">Support</a> (<code>HostRouting</code>) → <a href="#middleware">Middleware</a> (<code>Hostable</code>) → <a href="#facades">Facades</a> (<code>HostRouting</code>)</td></tr><tr><td>Real-time / chat</td><td><a href="#events-listeners">Events &amp; Listeners</a> → <a href="#notifications">Notifications</a> → <a href="#services">Services</a> (BroadcastManager) → <a href="#scheduled-jobs">Scheduled Jobs</a> (ChatableScheduler)</td></tr></tbody></table><p>→ Architecture deep-dives also live under the <a href="/system-reference/architecture">system reference</a> — cache, broadcasting, host routing, and module conventions are documented there.</p><hr><h2 id="activators" tabindex="-1">Activators <a class="header-anchor" href="#activators" aria-label="Permalink to &quot;Activators&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Activators/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Activators</code></p><p>Activators persist and resolve enable/disable state. Modularous splits activation into two layers — module-level (whether a module loads at all) and route-level (whether a specific route action inside a module is enabled).</p><table><thead><tr><th>Class</th><th>Persisted in</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/activators/modularous-activator"><code>ModularousActivator</code></a></td><td><code>modules_statuses.json</code> + cache</td><td>Stores and resolves module-level statuses (<code>enabled</code> / <code>disabled</code>)</td></tr><tr><td><a href="/system-reference/backend/activators/module-activator"><code>ModuleActivator</code></a></td><td><code>routes_statuses.json</code> per module</td><td>Stores and resolves route-level statuses inside a module</td></tr></tbody></table><p><strong>CLI integration</strong>: <a href="/guide/console/module/route-disable"><code>route:disable</code></a>, <a href="/guide/console/module/route-enable"><code>route:enable</code></a>, <a href="/guide/console/module/route-status"><code>route:status</code></a> read and mutate these files.</p><p>→ <a href="/system-reference/backend/activators/overview">Activators reference</a></p><hr><h2 id="brokers" tabindex="-1">Brokers <a class="header-anchor" href="#brokers" aria-label="Permalink to &quot;Brokers&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Brokers/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Brokers</code></p><p>Powers the email-verification-based registration flow behind the <a href="/system-reference/backend/facades/register"><code>Register</code> facade</a>. Mirrors Laravel&#39;s password broker design, adapted for verification tokens.</p><table><thead><tr><th>Class</th><th>Role</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/brokers/register-broker"><code>RegisterBroker</code></a></td><td>Executes verification-link and registration-token operations</td></tr><tr><td><a href="/system-reference/backend/brokers/register-broker-manager"><code>RegisterBrokerManager</code></a></td><td>Resolves named broker instances and selects the default broker</td></tr><tr><td><a href="/system-reference/backend/brokers/token-repository-interface"><code>TokenRepositoryInterface</code></a></td><td>Contract for email-based token repository methods</td></tr></tbody></table><p><strong>Flow</strong>: controller → <code>Register::broker()</code> → <code>RegisterBrokerManager</code> → <code>RegisterBroker</code> → <code>TokenRepositoryInterface</code>.</p><p>→ <a href="/system-reference/backend/brokers/overview">Brokers reference</a></p><hr><h2 id="console-commands" tabindex="-1">Console Commands <a class="header-anchor" href="#console-commands" aria-label="Permalink to &quot;Console Commands&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Console/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Console</code></p><p>Discovered via <code>CommandDiscovery::discover()</code> in <code>BaseServiceProvider</code>. Every command extends a <code>BaseCommand</code>, which adds module-aware option resolution and consistent output formatting on top of <code>Illuminate\\Console\\Command</code>.</p><table><thead><tr><th>Category</th><th>Path</th><th>Commands</th></tr></thead><tbody><tr><td>Cache</td><td><code>Console/Cache/</code></td><td><a href="/guide/console/cache/cache-clear"><code>cache:clear</code></a>, <a href="/guide/console/cache/cache-list"><code>cache:list</code></a>, <a href="/guide/console/cache/cache-warm"><code>cache:warm</code></a>, <a href="/guide/console/cache/cache-stats"><code>cache:stats</code></a>, <a href="/guide/console/cache/cache-versions"><code>cache:versions</code></a>, <a href="/guide/console/cache/cache-graph"><code>cache:graph</code></a></td></tr><tr><td>Coverage</td><td><code>Console/Coverage/</code></td><td><code>coverage:report</code>, <code>coverage:methods</code></td></tr><tr><td>Docs</td><td><code>Console/Docs/</code></td><td>Docs scaffolding helpers</td></tr><tr><td>Flush</td><td><code>Console/Flush/</code></td><td><a href="/guide/console/flush/flush"><code>flush</code></a>, <a href="/guide/console/flush/flush-filepond"><code>flush:filepond</code></a>, <a href="/guide/console/flush/flush-sessions"><code>flush:sessions</code></a></td></tr><tr><td>Make</td><td><code>Console/Make/</code></td><td><code>make:controller</code>, <code>make:controller-api</code>, <code>make:event</code>, <code>make:feature</code>, <code>make:input-hydrate</code>, <code>make:laravel-test</code>, <code>make:listener</code>, <code>make:migration</code>, <code>make:model</code>, <code>make:module</code>, <code>make:operation</code>, <code>make:repository</code>, <code>make:repository-trait</code>, <code>make:request</code>, <code>make:route</code>, <code>make:route-permissions</code>, <code>make:stubs</code>, <code>make:theme</code>, <code>make:vue-input</code>, <code>make:vue-test</code></td></tr><tr><td>Migration</td><td><code>Console/Migration/</code></td><td><code>migrate</code>, <code>migrate:refresh</code>, <code>migrate:rollback</code></td></tr><tr><td>Module</td><td><code>Console/Module/</code></td><td><code>module:fix</code>, <code>module:remove</code>, <code>route:disable</code>, <code>route:enable</code>, <a href="/guide/console/module/route-status"><code>route:status</code></a></td></tr><tr><td>Operations</td><td><code>Console/Operations/</code></td><td>Workflow / batch-operation runners</td></tr><tr><td>Setup</td><td><code>Console/Setup/</code></td><td><code>create-superadmin</code>, <a href="/guide/console/setup/create-database"><code>create:database</code></a>, <code>install</code>, <code>setup:dev</code></td></tr><tr><td>Sync</td><td><code>Console/Sync/</code></td><td><a href="/guide/console/sync/sync-states"><code>sync:states</code></a>, <a href="/guide/console/sync/sync-translations"><code>sync:translations</code></a></td></tr><tr><td>Top-level</td><td><code>Console/</code></td><td><a href="/guide/console/build"><code>build</code></a>, <code>composer:merge</code>, <code>composer:scripts</code>, <code>db:check-collation</code>, <code>dev</code>, <a href="/guide/console/pint"><code>pint</code></a>, <code>refresh</code>, <code>replace:regex</code>, <code>version</code></td></tr><tr><td>Update</td><td><code>Console/Update/</code></td><td>Module-update commands</td></tr></tbody></table><p>→ Per-command usage is documented in the <a href="/guide/console/overview">Console guide</a>.</p><hr><h2 id="controllers" tabindex="-1">Controllers <a class="header-anchor" href="#controllers" aria-label="Permalink to &quot;Controllers&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Http/Controllers/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers</code></p><p>The controller hierarchy is <strong>CoreController → PanelController → BaseController</strong>. Modules extend <code>BaseController</code> and configure form schemas, with each layer adding more module-aware behaviour.</p><table><thead><tr><th>Layer</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/http/controllers/core-controller"><code>CoreController</code></a></td><td>Base HTTP controller — shared response helpers</td></tr><tr><td><a href="/system-reference/backend/http/controllers/panel-controller"><code>PanelController</code></a></td><td>Route/model resolution, index options, authorization, <code>$this-&gt;repository</code></td></tr><tr><td><a href="/system-reference/backend/http/controllers/base-controller"><code>BaseController</code></a></td><td>View prefix, form schema, index/create/edit flow, <code>setupFormSchema()</code></td></tr></tbody></table><p><strong><code>BaseController</code> traits</strong>: <code>ManageIndexAjax</code>, <code>ManageInertia</code>, <code>ManagePrevious</code>, <code>ManageSingleton</code>, <code>ManageTranslations</code>.</p><p><strong>Request flow</strong>: <code>preload()</code> → <code>addWiths()</code> → <code>setupFormSchema()</code> → <code>index()</code> / <code>create()</code> / <code>edit()</code> → <code>respondToIndexAjax()</code> for AJAX.</p><p><strong>Concrete controllers</strong> (selection): <code>ApiController</code>, <code>ChatController</code>, <code>DashboardController</code>, <code>FileLibraryController</code>, <code>FilepondController</code>, <code>MediaLibraryController</code>, <code>MetricController</code>, <code>ProcessController</code>, <code>ProfileController</code>, <code>TagController</code>, <code>UiPreferencesController</code>, plus auth-scoped controllers under <code>Http/Controllers/Auth/</code>.</p><p>→ <a href="/system-reference/backend/http/controllers/overview">Full Controllers reference</a></p><hr><h2 id="entities" tabindex="-1">Entities <a class="header-anchor" href="#entities" aria-label="Permalink to &quot;Entities&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Entities/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Entities</code></p><p>~30 Eloquent models for users, content, files, processes, state, and communication, plus supporting <code>Casts/</code>, <code>Enums/</code>, <code>Interfaces/</code>, <code>Mutators/</code>, <code>Observers/</code>, <code>Scopes/</code>, <code>Traits/</code>, and <code>Translations/</code> subfolders. Module-generated models extend <code>Model</code> and gain soft-deletes, tagging, caching, presenter support, and trait composition out of the box.</p><table><thead><tr><th>Group</th><th>Models</th><th>Reference</th></tr></thead><tbody><tr><td><strong>Base classes</strong></td><td>Model, Revision</td><td><a href="/system-reference/backend/entities/model">Model →</a> · <a href="/system-reference/backend/entities/revision">Revision →</a></td></tr><tr><td><strong>Communication</strong></td><td>Chat, ChatMessage</td><td><a href="/system-reference/backend/entities/chat">Chat →</a> · <a href="/system-reference/backend/entities/chat-message">ChatMessage →</a></td></tr><tr><td><strong>Content building blocks</strong></td><td>Block, Repeater, Tag, Tagged</td><td><a href="/system-reference/backend/entities/block">Block →</a> · <a href="/system-reference/backend/entities/repeater">Repeater →</a> · <a href="/system-reference/backend/entities/tag">Tag →</a></td></tr><tr><td><strong>Files &amp; Media</strong></td><td>File, Filepond, Media, TemporaryFilepond</td><td><a href="/system-reference/backend/entities/file">File →</a> · <a href="/system-reference/backend/entities/filepond">Filepond →</a> · <a href="/system-reference/backend/entities/media">Media →</a></td></tr><tr><td><strong>Other</strong></td><td>Feature, NestedsetCollection, RelatedItem</td><td><a href="/system-reference/backend/entities/feature">Feature →</a> · <a href="/system-reference/backend/entities/nestedset-collection">NestedsetCollection →</a> · <a href="/system-reference/backend/entities/related-item">RelatedItem →</a></td></tr><tr><td><strong>Process &amp; Workflow</strong></td><td>Assignment, Authorization, CreatorRecord, Process, ProcessHistory</td><td><a href="/system-reference/backend/entities/assignment">Assignment →</a> · <a href="/system-reference/backend/entities/authorization">Authorization →</a> · <a href="/system-reference/backend/entities/process">Process →</a></td></tr><tr><td><strong>State &amp; Data</strong></td><td>Setting, Singleton, Spread, State, Stateable</td><td><a href="/system-reference/backend/entities/singleton">Singleton →</a> · <a href="/system-reference/backend/entities/state">State →</a> · <a href="/system-reference/backend/entities/stateable">Stateable →</a></td></tr><tr><td><strong>Users &amp; Auth</strong></td><td>Company, Profile, User, UserOauth</td><td><a href="/system-reference/backend/entities/company">Company →</a> · <a href="/system-reference/backend/entities/profile">Profile →</a> · <a href="/system-reference/backend/entities/user">User →</a></td></tr></tbody></table><p><strong>Enums</strong>: AssignmentStatus, PaymentStatus, Permission, ProcessStatus, RoleTeam, UserRole.</p><p>→ <a href="/system-reference/backend/entities/overview">Full Entities reference</a></p><hr><h2 id="entity-traits" tabindex="-1">Entity Traits <a class="header-anchor" href="#entity-traits" aria-label="Permalink to &quot;Entity Traits&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Entities/Traits/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Entities\\Traits</code></p><p>A library of traits (top-level + nested under <code>Auth/</code>, <code>Core/</code>, <code>Secondary/</code>) covering relationships, accessors, scopes, lifecycle hooks, and broadcasting context. Each trait composes onto an entity to add a self-contained behaviour without subclassing.</p><table><thead><tr><th>Group</th><th>Examples</th><th>Reference</th></tr></thead><tbody><tr><td><strong>Auth</strong></td><td>CanRegister, HasOauth</td><td><a href="/system-reference/backend/entity-traits/auth/overview">Auth →</a></td></tr><tr><td><strong>Core (top-level)</strong></td><td>HasPosition, HasPresenter, HasSlug, HasSpreadable, HasStateable, HasUuid</td><td><a href="/system-reference/backend/entity-traits/core/overview">Core →</a></td></tr><tr><td><strong>Media</strong></td><td>HasFileponds, HasFiles, HasImages</td><td><a href="/system-reference/backend/entity-traits/media/overview">Media →</a></td></tr><tr><td><strong>Model behavior</strong></td><td>HasPosition, HasPresenter, HasSlug, HasSpreadable, HasStateable, HasUuid</td><td><a href="/system-reference/backend/entity-traits/model-behavior/overview">Model behavior →</a></td></tr><tr><td><strong>Payment</strong></td><td>HasPayment, HasPriceable</td><td><a href="/system-reference/backend/entity-traits/payment/overview">Payment →</a></td></tr><tr><td><strong>Processes</strong></td><td>HasProcesses, Processable</td><td><a href="/system-reference/backend/entity-traits/processes/overview">Processes →</a></td></tr><tr><td><strong>Relationships</strong></td><td>Assignable, Chatable, HasAuthorizable, HasCreator</td><td><a href="/system-reference/backend/entity-traits/relationships/overview">Relationships →</a></td></tr><tr><td><strong>Repeaters</strong></td><td>HasRepeaters</td><td><a href="/system-reference/backend/entity-traits/repeaters/overview">Repeaters →</a></td></tr><tr><td><strong>Secondary</strong></td><td>HasBlocks, HasNesting, HasRelated, HasRevisions</td><td><a href="/system-reference/backend/entity-traits/secondary/overview">Secondary →</a></td></tr><tr><td><strong>Singletons</strong></td><td>IsHostable, IsSingular</td><td><a href="/system-reference/backend/entity-traits/singletons/overview">Singletons →</a></td></tr><tr><td><strong>Translation</strong></td><td>HasTranslation, IsTranslatable</td><td><a href="/system-reference/backend/entity-traits/translation/overview">Translation →</a></td></tr></tbody></table><p>→ <a href="/system-reference/backend/entity-traits/overview">Full Entity Traits reference</a></p><hr><h2 id="events-listeners" tabindex="-1">Events &amp; Listeners <a class="header-anchor" href="#events-listeners" aria-label="Permalink to &quot;Events &amp; Listeners&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Events/</code>, <code>src/Listeners/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Events</code>, <code>Unusualify\\Modularous\\Listeners</code></p><p>Events fire at lifecycle boundaries (model created/updated, user registered, state changed). Listeners react and, when mail is enabled, dispatch the matching notification.</p><table><thead><tr><th>Class</th><th>Role</th><th>Page</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/events/listener"><code>Listener</code></a></td><td>Abstract base for listeners — resolves notification class from event name</td><td>Class reference</td></tr><tr><td><a href="/system-reference/backend/events/model-event"><code>ModelEvent</code></a></td><td>Abstract base — composes <code>EventChanges</code>, <code>EventStateable</code>, <code>EventUrls</code>, <code>EventUser</code> traits and provides broadcasting defaults</td><td>Class reference</td></tr><tr><td><a href="/system-reference/backend/events/user-events">User events</a></td><td><code>ModularousUserRegistered</code>, <code>ModularousUserRegistering</code>, <code>ModularousUserVerification</code>, <code>VerifiedEmailRegister</code></td><td>Auth events</td></tr></tbody></table><p><strong>Event traits</strong> (under <code>events/traits/</code>): <a href="/system-reference/backend/events/traits/event-changes"><code>EventChanges</code></a>, <a href="/system-reference/backend/events/traits/event-stateable"><code>EventStateable</code></a>, <a href="/system-reference/backend/events/traits/event-urls"><code>EventUrls</code></a>, <a href="/system-reference/backend/events/traits/event-user"><code>EventUser</code></a>. Each is auto-set up in <code>ModelEvent</code>&#39;s constructor and its public properties are serialized into broadcast payloads.</p><p>→ <a href="/system-reference/backend/events/overview">Full Events reference</a> → Real-time setup, Echo integration, testing, and troubleshooting are covered in the <a href="/guide/broadcasting/overview">Broadcasting guide</a>.</p><hr><h2 id="facades" tabindex="-1">Facades <a class="header-anchor" href="#facades" aria-label="Permalink to &quot;Facades&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Facades/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Facades</code></p><p>18 Laravel facades providing static-style access to bound services. Each facade aliases a container entry to a concrete service class.</p><p><strong>Selected facades</strong>: <a href="/system-reference/backend/facades/coverage"><code>Coverage</code></a>, <a href="/system-reference/backend/facades/currency-exchange"><code>CurrencyExchange</code></a>, <a href="/system-reference/backend/facades/filepond"><code>Filepond</code></a>, <a href="/system-reference/backend/facades/host-routing"><code>HostRouting</code></a>, <a href="/system-reference/backend/facades/migration-backup"><code>MigrationBackup</code></a>, <a href="/system-reference/backend/facades/modularous"><code>Modularous</code></a>, <a href="/system-reference/backend/facades/modularous-cache"><code>ModularousCache</code></a>, <a href="/system-reference/backend/facades/modularous-routes"><code>ModularousRoutes</code></a>, <a href="/system-reference/backend/facades/modularous-vite"><code>ModularousVite</code></a>, <a href="/system-reference/backend/facades/navigation"><code>Navigation</code></a>, <a href="/system-reference/backend/facades/redirect"><code>Redirect</code></a>, <a href="/system-reference/backend/facades/register"><code>Register</code></a>, <a href="/system-reference/backend/facades/relationship-graph"><code>RelationshipGraph</code></a>, <a href="/system-reference/backend/facades/utm"><code>Utm</code></a>.</p><p>→ <a href="/system-reference/backend/facades/overview">Full Facades reference</a></p><hr><h2 id="form-requests" tabindex="-1">Form Requests <a class="header-anchor" href="#form-requests" aria-label="Permalink to &quot;Form Requests&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Http/Requests/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Requests</code></p><p>Form Request classes that validate, authorize, and shape incoming requests for module endpoints. Extend Laravel&#39;s <code>FormRequest</code> with module-aware authorization and translation hooks.</p><table><thead><tr><th>Class</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/http/request/base-form-request"><code>BaseFormRequest</code></a></td><td>Shared validation/authorization plumbing</td></tr><tr><td><a href="/system-reference/backend/http/request/file-request"><code>FileRequest</code></a></td><td>File upload validation</td></tr><tr><td><a href="/system-reference/backend/http/request/media-request"><code>MediaRequest</code></a></td><td>Media upload validation</td></tr><tr><td><a href="/system-reference/backend/http/request/oauth-request"><code>OAuthRequest</code></a></td><td>OAuth callback payload validation</td></tr><tr><td><a href="/system-reference/backend/http/request/request"><code>Request</code></a></td><td>Generic module-aware base form request</td></tr><tr><td><a href="/system-reference/backend/http/request/store-permission-request"><code>StorePermissionRequest</code></a></td><td>Permission creation</td></tr><tr><td><a href="/system-reference/backend/http/request/store-role-request"><code>StoreRoleRequest</code></a></td><td>Role creation</td></tr></tbody></table><p>→ <a href="/system-reference/backend/http/request/overview">Full Form Requests reference</a></p><hr><h2 id="generators" tabindex="-1">Generators <a class="header-anchor" href="#generators" aria-label="Permalink to &quot;Generators&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Generators/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Generators</code></p><p>Scaffolding engine behind <code>make:*</code> and <code>make:route</code> commands. Produces the full PHP and JS file set for new module routes plus test scaffolding for both backend and frontend.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generator (abstract)                ← NwidartGenerator + ReplacementTrait</span></span>
<span class="line"><span>├── RouteGenerator                  ← full-stack route scaffolding (primary)</span></span>
<span class="line"><span>├── StubsGenerator                  ← stub-only regeneration (fix/patch)</span></span>
<span class="line"><span>├── VueTestGenerator                ← Vitest/Jest test scaffolding</span></span>
<span class="line"><span>└── LaravelTestGenerator            ← PHPUnit test scaffolding</span></span></code></pre></div><table><thead><tr><th>Generator</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/generators/generator"><code>Generator</code></a></td><td>Abstract base — module resolution, config path helpers</td></tr><tr><td><a href="/system-reference/backend/generators/laravel-test-generator"><code>LaravelTestGenerator</code></a></td><td>PHPUnit Unit or Feature test scaffolding</td></tr><tr><td><a href="/system-reference/backend/generators/route-generator"><code>RouteGenerator</code></a></td><td>Full set of files for a new module route (model, migration, controller, repository, request, translations, permissions)</td></tr><tr><td><a href="/system-reference/backend/generators/stubs-generator"><code>StubsGenerator</code></a></td><td>Selective stub regeneration with <code>only</code> / <code>except</code> lists</td></tr><tr><td><a href="/system-reference/backend/generators/vue-test-generator"><code>VueTestGenerator</code></a></td><td>Vue component / composable / utility / store test scaffolding</td></tr></tbody></table><p>→ <a href="/system-reference/backend/generators/overview">Full Generators reference</a></p><hr><h2 id="helpers" tabindex="-1">Helpers <a class="header-anchor" href="#helpers" aria-label="Permalink to &quot;Helpers&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Helpers/</code> · <strong>Namespace</strong>: global functions</p><p>15 PHP helper files exposing 100+ global functions. Loaded by Composer autoload, available everywhere.</p><table><thead><tr><th>File</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/helpers/array"><code>array</code></a></td><td>Array shape transforms</td></tr><tr><td><a href="/system-reference/backend/helpers/column"><code>column</code></a></td><td>Column metadata helpers</td></tr><tr><td><a href="/system-reference/backend/helpers/component"><code>component</code></a></td><td>Frontend component resolution</td></tr><tr><td><a href="/system-reference/backend/helpers/composer"><code>composer</code></a></td><td>Composer JSON parsing</td></tr><tr><td><a href="/system-reference/backend/helpers/connector"><code>connector</code></a></td><td>External-service connector helpers</td></tr><tr><td><a href="/system-reference/backend/helpers/db"><code>db</code></a></td><td>Schema introspection (<code>hasColumn</code>, <code>hasIndex</code>, etc.)</td></tr><tr><td><a href="/system-reference/backend/helpers/format"><code>format</code></a></td><td>Currency / date / number formatting</td></tr><tr><td><a href="/system-reference/backend/helpers/front"><code>front</code></a></td><td>Frontend URL/asset helpers</td></tr><tr><td><a href="/system-reference/backend/helpers/i18n"><code>i18n</code></a></td><td>Locale and translation helpers</td></tr><tr><td><a href="/system-reference/backend/helpers/input"><code>input</code></a></td><td>Input schema / hydrate helpers</td></tr><tr><td><a href="/system-reference/backend/helpers/media"><code>media</code></a></td><td>Image URL / disk resolution</td></tr><tr><td><a href="/system-reference/backend/helpers/migrations"><code>migrations</code></a></td><td>Migration build helpers</td></tr><tr><td><a href="/system-reference/backend/helpers/module"><code>module</code></a></td><td><code>modularousConfig()</code>, <code>module_path()</code>, <code>currentModule()</code></td></tr><tr><td><a href="/system-reference/backend/helpers/router"><code>router</code></a></td><td>Route resolution helpers</td></tr><tr><td><a href="/system-reference/backend/helpers/sources"><code>sources</code></a></td><td>Module path discovery</td></tr></tbody></table><p>→ <a href="/system-reference/backend/helpers/overview">Full Helpers reference</a></p><hr><h2 id="middleware" tabindex="-1">Middleware <a class="header-anchor" href="#middleware" aria-label="Permalink to &quot;Middleware&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Http/Middleware/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Middleware</code></p><p>14 middleware classes registered via <code>BaseServiceProvider</code> and grouped into pipelines for admin, auth, and API routes.</p><table><thead><tr><th>Middleware</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/http/middleware/authenticate"><code>Authenticate</code></a></td><td>Modularous-aware auth guard</td></tr><tr><td><a href="/system-reference/backend/http/middleware/authorization"><code>Authorization</code></a></td><td>Permission/role enforcement</td></tr><tr><td><a href="/system-reference/backend/http/middleware/company-registration"><code>CompanyRegistration</code></a></td><td>Company onboarding gate</td></tr><tr><td><a href="/system-reference/backend/http/middleware/handle-inertia-requests"><code>HandleInertiaRequests</code></a></td><td>Inertia shared props</td></tr><tr><td><a href="/system-reference/backend/http/middleware/hostable"><code>Hostable</code></a></td><td>Host-based routing resolution</td></tr><tr><td><a href="/system-reference/backend/http/middleware/impersonate"><code>Impersonate</code></a></td><td>User impersonation gate</td></tr><tr><td><a href="/system-reference/backend/http/middleware/language"><code>Language</code></a></td><td>Locale resolution from URL/header</td></tr><tr><td><a href="/system-reference/backend/http/middleware/load-localized-config"><code>LoadLocalizedConfig</code></a></td><td>Locale-specific config loading</td></tr><tr><td><a href="/system-reference/backend/http/middleware/log"><code>Log</code></a></td><td>Request logging</td></tr><tr><td><a href="/system-reference/backend/http/middleware/navigation"><code>Navigation</code></a></td><td>Sidebar nav assembly</td></tr><tr><td><a href="/system-reference/backend/http/middleware/redirect-if-authenticated"><code>RedirectIfAuthenticated</code></a></td><td>Guest-only routes</td></tr><tr><td><a href="/system-reference/backend/http/middleware/redirector"><code>Redirector</code></a></td><td>Configured redirect rules</td></tr><tr><td><a href="/system-reference/backend/http/middleware/teams-permission"><code>TeamsPermission</code></a></td><td>Team-aware permission resolution</td></tr><tr><td><a href="/system-reference/backend/http/middleware/utm"><code>Utm</code></a></td><td>UTM parameter capture</td></tr></tbody></table><p>→ <a href="/system-reference/backend/http/middleware/overview">Full Middleware reference</a></p><hr><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Notifications/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Notifications</code></p><table><thead><tr><th>Group</th><th>Classes</th><th>Page</th></tr></thead><tbody><tr><td><strong>Auth notifications</strong></td><td><code>EmailVerification</code>, <code>GeneratePasswordNotification</code>, <code>ResetPasswordNotification</code></td><td><a href="/system-reference/backend/notifications/auth-notifications">Auth notifications →</a></td></tr><tr><td><strong>Feature base</strong></td><td><code>FeatureNotification</code></td><td><a href="/system-reference/backend/notifications/feature-notification">FeatureNotification →</a></td></tr><tr><td><strong>System notifications</strong></td><td>11 system notification classes (model lifecycle, payments, assignments, chat, state changes)</td><td><a href="/system-reference/backend/notifications/system-notifications">System notifications →</a></td></tr></tbody></table><p>Notifications are dispatched by <code>Listener::handle()</code> when <code>modularous.mail.enabled = true</code> and the listener resolves a <code>{EventName}Notification</code> class.</p><p>→ <a href="/system-reference/backend/notifications/overview">Full Notifications reference</a></p><hr><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Providers/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Providers</code></p><p>Service providers wire the package into the host Laravel app. Bind services, publish config, register routes, hook view composers, wire the scheduler, and discover commands.</p><table><thead><tr><th>Provider</th><th>Role</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/providers/auth-service-provider"><code>AuthServiceProvider</code></a></td><td>Modularous policies and gates</td></tr><tr><td><a href="/system-reference/backend/providers/base-service-provider"><code>BaseServiceProvider</code></a></td><td>Core bindings, command discovery, view composers, scheduler, middleware aliases</td></tr><tr><td><a href="/system-reference/backend/providers/coverage-service-provider"><code>CoverageServiceProvider</code></a></td><td>Coverage analyzer + commands binding</td></tr><tr><td><a href="/system-reference/backend/providers/modularous-provider"><code>ModularousProvider</code></a></td><td>Top-level provider — registers all child providers</td></tr><tr><td><a href="/system-reference/backend/providers/module-service-provider"><code>ModuleServiceProvider</code></a></td><td>Per-module provider auto-generated for each module</td></tr><tr><td><a href="/system-reference/backend/providers/route-service-provider"><code>RouteServiceProvider</code></a></td><td>Module route registration with host/permission groups</td></tr><tr><td><a href="/system-reference/backend/providers/service-provider"><code>ServiceProvider</code></a></td><td>Abstract base with config publishing helpers</td></tr><tr><td><a href="/system-reference/backend/providers/telescope-service-provider"><code>TelescopeServiceProvider</code></a></td><td>Telescope integration when present</td></tr></tbody></table><p>→ <a href="/system-reference/backend/providers/overview">Full Providers reference</a></p><hr><h2 id="repository-traits" tabindex="-1">Repository Traits <a class="header-anchor" href="#repository-traits" aria-label="Permalink to &quot;Repository Traits&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Repositories/Traits/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Repositories\\Traits</code></p><p>Repository traits extend the base <code>Repository</code> class with domain-specific persistence logic. While <a href="/system-reference/backend/entity-traits/overview">Entity Traits</a> define model-level behaviour, repository traits handle <strong>how data flows in and out</strong> — form field hydration, after-save side effects, table filters, caching.</p><p>Every repository trait follows a naming convention that the base <code>Repository</code> discovers and invokes at the right lifecycle stage:</p><table><thead><tr><th>Convention</th><th>When called</th></tr></thead><tbody><tr><td><code>setColumns{Trait}</code></td><td>Boot — registers form input names this trait manages</td></tr><tr><td><code>prepareFieldsBeforeCreate{Trait}</code></td><td>Before insert</td></tr><tr><td><code>prepareFieldsBeforeSave{Trait}</code></td><td>Before any save</td></tr><tr><td><code>beforeSave{Trait}</code> / <code>afterSave{Trait}</code></td><td>Around the Eloquent <code>save()</code> call</td></tr><tr><td><code>hydrate{Trait}</code></td><td>Sets in-memory relationships before save (preview/validation)</td></tr><tr><td><code>getFormFields{Trait}</code></td><td>Populates form fields when editing</td></tr><tr><td><code>afterDelete{Trait}</code> / <code>afterRestore{Trait}</code></td><td>Soft-delete + restore hooks</td></tr><tr><td><code>filter{Trait}</code> / <code>order{Trait}</code></td><td>Index query scopes / ordering</td></tr><tr><td><code>getTableFilters{Trait}</code></td><td>Filter tab definitions for the data table UI</td></tr><tr><td><code>getFormActions{Trait}</code></td><td>Form action button definitions</td></tr></tbody></table><table><thead><tr><th>Group</th><th>Page</th></tr></thead><tbody><tr><td>Content (Blocks, Repeaters)</td><td><a href="/system-reference/backend/repository-traits/content">Content →</a></td></tr><tr><td>Logic helpers (caching, schema, query building)</td><td><a href="/system-reference/backend/repository-traits/logic/overview">Logic →</a></td></tr><tr><td>Media (Files, Images, Filepond)</td><td><a href="/system-reference/backend/repository-traits/media">Media →</a></td></tr><tr><td>OAuth</td><td><a href="/system-reference/backend/repository-traits/oauth">OAuth →</a></td></tr><tr><td>Payment</td><td><a href="/system-reference/backend/repository-traits/payment">Payment →</a></td></tr><tr><td>Processes</td><td><a href="/system-reference/backend/repository-traits/processes">Processes →</a></td></tr><tr><td>Relationships</td><td><a href="/system-reference/backend/repository-traits/relationships">Relationships →</a></td></tr><tr><td>State</td><td><a href="/system-reference/backend/repository-traits/state">State →</a></td></tr></tbody></table><p>→ <a href="/system-reference/backend/repository-traits/overview">Full Repository Traits reference</a></p><hr><h2 id="scheduled-jobs" tabindex="-1">Scheduled Jobs <a class="header-anchor" href="#scheduled-jobs" aria-label="Permalink to &quot;Scheduled Jobs&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Schedulers/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Schedulers</code></p><p>Background jobs auto-discovered from <code>src/Schedulers/*.php</code> via <code>CommandDiscovery</code> and registered against Laravel&#39;s <code>Schedule</code> inside <code>BaseServiceProvider::boot()</code> (no <code>Console\\Kernel.php</code> is required in the host app).</p><table><thead><tr><th>Command</th><th>Class</th><th>Cadence</th><th>Purpose</th></tr></thead><tbody><tr><td><code>modularous:fileponds:scheduler</code></td><td><a href="/system-reference/backend/scheduled-jobs/fileponds-scheduler"><code>FilepondsScheduler</code></a></td><td>Daily</td><td>Cleans up orphaned <code>temporary_fileponds</code> rows + their files</td></tr><tr><td><code>modularous:scheduler:chatable</code></td><td><a href="/system-reference/backend/scheduled-jobs/chatable-scheduler"><code>ChatableScheduler</code></a></td><td>Every minute</td><td>Aggregates unread chat messages and dispatches <code>UnreadChatMessage</code> notifications</td></tr><tr><td><code>telescope:prune</code></td><td>(Laravel Telescope)</td><td>Daily</td><td>Prunes Telescope entries older than 168 hours</td></tr></tbody></table><p>Both Modularous schedulers can also be run manually as Artisan commands. Output goes to the <code>scheduler</code> log channel; the host server only needs the standard <code>* * * * * php artisan schedule:run</code> cron entry.</p><p>→ <a href="/system-reference/backend/scheduled-jobs/overview">Full Scheduled Jobs reference</a></p><hr><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Services/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Services</code></p><p>Bound in the service container; injected via constructor or accessed through their dedicated <a href="#facades">Facades</a>. Each group has its own reference page.</p><table><thead><tr><th>Group</th><th>Members</th><th>Page</th></tr></thead><tbody><tr><td><strong>Cache concerns</strong></td><td>CacheHelpers, CacheInvalidation, CacheTags</td><td><a href="/system-reference/backend/services/cache-concerns/overview">Cache Concerns →</a></td></tr><tr><td><strong>Core services</strong></td><td>Assets, BroadcastManager, Connector, CoverageService, CurrencyExchangeService, FilepondManager, FileTranslation, MessageStage, MigrationBackup, ModularousCacheService, RedirectService, Translation, UtmParameters</td><td><a href="/system-reference/backend/services/overview">Services →</a></td></tr><tr><td><strong>Currency</strong></td><td>NullCurrencyProvider, SystemPricingCurrencyProvider</td><td><a href="/system-reference/backend/services/currency/overview">Currency →</a></td></tr><tr><td><strong>FileLibrary</strong></td><td>Disk, FileService</td><td><a href="/system-reference/backend/services/file-library/overview">FileLibrary →</a></td></tr><tr><td><strong>MediaLibrary</strong></td><td>Glide, Imgix, Local, TwicPics drivers</td><td><a href="/system-reference/backend/services/media-library/overview">MediaLibrary →</a></td></tr><tr><td><strong>Uploader</strong></td><td>SignAzureUpload, SignS3Upload, SignUploadListener</td><td><a href="/system-reference/backend/services/uploader/overview">Uploader →</a></td></tr><tr><td><strong>View services</strong></td><td>ModularousNavigation, UComponent, UWidget, UWrapper</td><td><a href="/system-reference/backend/services/view/overview">View Services →</a></td></tr></tbody></table><p><strong>Cache support</strong>: <a href="/system-reference/backend/services/cache-relationship-graph"><code>CacheRelationshipGraph</code></a> drives cross-entity cache invalidation. The CLI face is <a href="/guide/console/cache/cache-graph"><code>cache:graph</code></a>.</p><p>→ <a href="/system-reference/backend/services/overview">Full Services reference</a></p><hr><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Support/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Support</code></p><p>Stateless utility classes used across the codebase for command discovery, schema parsing, route grouping, and host-based routing.</p><table><thead><tr><th>Class</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/support/command-discovery"><code>CommandDiscovery</code></a></td><td>Scan glob paths and return instantiable <code>Command</code> FQCNs</td></tr><tr><td><a href="/system-reference/backend/support/coverage-analyzer"><code>CoverageAnalyzer</code></a></td><td>Parse Clover XML and report per-method coverage</td></tr><tr><td><a href="/system-reference/backend/support/decomposers"><code>Decomposers</code></a></td><td>Parse schema/relation/validation strings for generators</td></tr><tr><td><a href="/system-reference/backend/support/file-loader"><code>FileLoader</code></a></td><td>Translation file loader with multi-path support</td></tr><tr><td><a href="/system-reference/backend/support/finder"><code>Finder</code></a></td><td>Resolve model/repository by table name or route name</td></tr><tr><td><a href="/system-reference/backend/support/host-routing"><code>HostRouting / HostRouteRegistrar</code></a></td><td>Multi-tenant host-based route groups</td></tr><tr><td><a href="/system-reference/backend/support/migrations-schema-parser"><code>Migrations\\SchemaParser</code></a></td><td>Render migration <code>$table-&gt;…</code> PHP from schema strings</td></tr><tr><td><a href="/system-reference/backend/support/modularous-routes"><code>ModularousRoutes</code></a></td><td>Route group options and middleware alias registration</td></tr><tr><td><a href="/system-reference/backend/support/modularous-vite"><code>ModularousVite</code></a></td><td>Vite integration for the Modularous asset manifest</td></tr><tr><td><a href="/system-reference/backend/support/regex-replacement"><code>RegexReplacement</code></a></td><td>Batch regex find-and-replace across a directory tree</td></tr></tbody></table><p>→ <a href="/system-reference/backend/support/overview">Full Support reference</a></p><hr><h2 id="view-composers" tabindex="-1">View Composers <a class="header-anchor" href="#view-composers" aria-label="Permalink to &quot;View Composers&quot;">​</a></h2><p><strong>Directory</strong>: <code>src/Http/ViewComposers/</code> · <strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\ViewComposers</code></p><p>Inject shared variables into Blade / Inertia layouts. Wired in <code>BaseServiceProvider::registerViewComposers()</code>.</p><table><thead><tr><th>Composer</th><th>Views</th><th>Condition</th></tr></thead><tbody><tr><td><a href="/system-reference/backend/http/view-composers/active-navigation"><code>ActiveNavigation</code></a></td><td>layouts with sidebar</td><td>Always</td></tr><tr><td><a href="/system-reference/backend/http/view-composers/current-user"><code>CurrentUser</code></a></td><td><code>admin.*</code>, <code>{baseKey}::*</code></td><td><code>enabled.users-management</code> = true</td></tr><tr><td><a href="/system-reference/backend/http/view-composers/files-uploader-config"><code>FilesUploaderConfig</code></a></td><td>master/app-inertia layouts</td><td><code>enabled.file-library</code> = true</td></tr><tr><td><a href="/system-reference/backend/http/view-composers/localization"><code>Localization</code></a></td><td>master/auth/app-inertia layouts</td><td>Always</td></tr><tr><td><a href="/system-reference/backend/http/view-composers/medias-uploader-config"><code>MediasUploaderConfig</code></a></td><td>master/app-inertia layouts</td><td><code>enabled.media-library</code> = true</td></tr><tr><td><a href="/system-reference/backend/http/view-composers/urls"><code>Urls</code></a></td><td><code>*</code></td><td>Always</td></tr></tbody></table><p>→ <a href="/system-reference/backend/http/view-composers/overview">Full View Composers reference</a></p><hr><h2 id="cross-cutting-concerns" tabindex="-1">Cross-cutting concerns <a class="header-anchor" href="#cross-cutting-concerns" aria-label="Permalink to &quot;Cross-cutting concerns&quot;">​</a></h2><p>A few capabilities don&#39;t live in a single section — they thread through several layers at once. Subsections below are ordered alphabetically; use them as a map to find every place a given concern shows up.</p><h3 id="authentication-authorization-registration" tabindex="-1">Authentication, authorization &amp; registration <a class="header-anchor" href="#authentication-authorization-registration" aria-label="Permalink to &quot;Authentication, authorization &amp; registration&quot;">​</a></h3><p>Auth is split between the request pipeline (middleware), the Spatie permission stack (gates/policies), and a verification-token broker for self-service registration.</p><table><thead><tr><th>Layer</th><th>Component</th></tr></thead><tbody><tr><td>Brokers</td><td><a href="/system-reference/backend/brokers/overview"><code>RegisterBroker</code>, <code>RegisterBrokerManager</code>, <code>TokenRepositoryInterface</code></a></td></tr><tr><td>Controllers</td><td><code>Http/Controllers/Auth/*</code></td></tr><tr><td>Entities &amp; Traits</td><td><code>Company</code>, <code>Profile</code>, <code>User</code>, <code>UserOauth</code>; <code>CanRegister</code>, <code>HasOauth</code></td></tr><tr><td>Enums</td><td><code>Permission</code>, <code>RoleTeam</code>, <code>UserRole</code></td></tr><tr><td>Form Requests</td><td><code>OAuthRequest</code>, <code>StorePermissionRequest</code>, <code>StoreRoleRequest</code></td></tr><tr><td>Middleware</td><td><a href="/system-reference/backend/http/middleware/authenticate"><code>Authenticate</code></a>, <a href="/system-reference/backend/http/middleware/authorization"><code>Authorization</code></a>, <a href="/system-reference/backend/http/middleware/company-registration"><code>CompanyRegistration</code></a>, <a href="/system-reference/backend/http/middleware/impersonate"><code>Impersonate</code></a>, <a href="/system-reference/backend/http/middleware/redirect-if-authenticated"><code>RedirectIfAuthenticated</code></a>, <a href="/system-reference/backend/http/middleware/teams-permission"><code>TeamsPermission</code></a></td></tr><tr><td>Notifications</td><td><code>EmailVerification</code>, <code>GeneratePasswordNotification</code>, <code>ResetPasswordNotification</code></td></tr><tr><td>Providers</td><td><a href="/system-reference/backend/providers/auth-service-provider"><code>AuthServiceProvider</code></a></td></tr></tbody></table><h3 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h3><p>Modularous ships a versioned, tag-aware cache built on top of Laravel&#39;s cache. Invalidation propagates through a relationship graph so editing a model also flushes anything that depends on it.</p><table><thead><tr><th>Layer</th><th>Component</th></tr></thead><tbody><tr><td>Bind / boot</td><td><code>BaseServiceProvider</code> (registers <code>ModularousCacheService</code>, <code>CacheRelationshipGraph</code>)</td></tr><tr><td>CLI</td><td><a href="/guide/console/cache/cache-clear"><code>cache:clear</code></a>, <a href="/guide/console/cache/cache-graph"><code>cache:graph</code></a>, <a href="/guide/console/cache/cache-list"><code>cache:list</code></a>, <a href="/guide/console/cache/cache-stats"><code>cache:stats</code></a>, <a href="/guide/console/cache/cache-versions"><code>cache:versions</code></a>, <a href="/guide/console/cache/cache-warm"><code>cache:warm</code></a></td></tr><tr><td>Concerns</td><td><a href="/system-reference/backend/services/cache-concerns/overview"><code>CacheHelpers</code>, <code>CacheInvalidation</code>, <code>CacheTags</code></a></td></tr><tr><td>Day-to-day API</td><td><a href="/system-reference/backend/facades/modularous-cache"><code>ModularousCache</code></a> facade, <a href="/system-reference/backend/services/cache-relationship-graph"><code>CacheRelationshipGraph</code></a></td></tr><tr><td>Repository hooks</td><td><a href="/system-reference/backend/repository-traits/logic/overview">Repository Traits → Logic</a> (<code>afterSave{Trait}</code>, <code>afterDelete{Trait}</code>)</td></tr></tbody></table><p>→ Full deep-dive: <a href="/system-reference/backend/services/modularous-cache-service">ModularousCacheService</a>.</p><h3 id="file-media-uploads" tabindex="-1">File &amp; media uploads <a class="header-anchor" href="#file-media-uploads" aria-label="Permalink to &quot;File &amp; media uploads&quot;">​</a></h3><p>Three independent upload pipelines share the same general shape (Form Request → Service → Entity Trait).</p><table><thead><tr><th>Pipeline</th><th>Controller</th><th>Service</th><th>Entity Trait</th><th>Repository Trait</th></tr></thead><tbody><tr><td>Direct cloud uploads</td><td>—</td><td><a href="/system-reference/backend/services/uploader/overview">Uploader</a> (<code>SignAzureUpload</code>, <code>SignS3Upload</code>)</td><td>—</td><td>—</td></tr><tr><td>File library</td><td><code>FileLibraryController</code></td><td><a href="/system-reference/backend/services/file-library/overview">FileLibrary</a></td><td><code>HasFiles</code></td><td><a href="/system-reference/backend/repository-traits/media">Media</a></td></tr><tr><td>Filepond (chunked uploads)</td><td><code>FilepondController</code></td><td><a href="/system-reference/backend/services/overview"><code>FilepondManager</code></a></td><td><code>HasFileponds</code></td><td><a href="/system-reference/backend/repository-traits/media">Media</a></td></tr><tr><td>Media library (image variants)</td><td><code>MediaLibraryController</code></td><td><a href="/system-reference/backend/services/media-library/overview">MediaLibrary</a></td><td><code>HasImages</code></td><td><a href="/system-reference/backend/repository-traits/media">Media</a></td></tr></tbody></table><h3 id="module-scaffolding-generation" tabindex="-1">Module scaffolding &amp; generation <a class="header-anchor" href="#module-scaffolding-generation" aria-label="Permalink to &quot;Module scaffolding &amp; generation&quot;">​</a></h3><p>Build-time only — these run from the CLI to produce or regenerate code.</p><table><thead><tr><th>Layer</th><th>Component</th></tr></thead><tbody><tr><td>CLI</td><td><code>make:*</code> commands (<a href="#console-commands">Console Commands</a>)</td></tr><tr><td>Generators</td><td><a href="#generators"><code>Generator</code>, <code>LaravelTestGenerator</code>, <code>RouteGenerator</code>, <code>StubsGenerator</code>, <code>VueTestGenerator</code></a></td></tr><tr><td>Support</td><td><a href="/system-reference/backend/support/decomposers"><code>Decomposers</code></a>, <a href="/system-reference/backend/support/migrations-schema-parser"><code>Migrations\\SchemaParser</code></a>, <a href="/system-reference/backend/support/regex-replacement"><code>RegexReplacement</code></a></td></tr></tbody></table><p>→ End-to-end walkthrough: <a href="/system-reference/modules">Modules reference</a>.</p><h3 id="multi-tenant-host-based-routing" tabindex="-1">Multi-tenant / host-based routing <a class="header-anchor" href="#multi-tenant-host-based-routing" aria-label="Permalink to &quot;Multi-tenant / host-based routing&quot;">​</a></h3><p>When the same module needs to serve different domains with different middleware or permission groups.</p><table><thead><tr><th>Layer</th><th>Component</th></tr></thead><tbody><tr><td>Entity Traits</td><td><code>IsHostable</code>, <code>IsSingular</code></td></tr><tr><td>Facade</td><td><a href="/system-reference/backend/facades/host-routing"><code>HostRouting</code></a></td></tr><tr><td>Middleware</td><td><a href="/system-reference/backend/http/middleware/hostable"><code>Hostable</code></a></td></tr><tr><td>Provider</td><td><a href="/system-reference/backend/providers/route-service-provider"><code>RouteServiceProvider</code></a></td></tr><tr><td>Support</td><td><a href="/system-reference/backend/support/host-routing"><code>HostRouting / HostRouteRegistrar</code></a>, <a href="/system-reference/backend/support/modularous-routes"><code>ModularousRoutes</code></a></td></tr></tbody></table><h3 id="real-time-broadcasting" tabindex="-1">Real-time broadcasting <a class="header-anchor" href="#real-time-broadcasting" aria-label="Permalink to &quot;Real-time broadcasting&quot;">​</a></h3><p>Model lifecycle and chat events broadcast over Laravel Echo when broadcasting is enabled.</p><table><thead><tr><th>Layer</th><th>Component</th></tr></thead><tbody><tr><td>Base classes</td><td><a href="/system-reference/backend/events/listener"><code>Listener</code></a>, <a href="/system-reference/backend/events/model-event"><code>ModelEvent</code></a> (with <a href="/system-reference/backend/events/overview">event traits</a>)</td></tr><tr><td>Entity Traits</td><td><code>Chatable</code>, <code>HasProcesses</code>, <code>HasStateable</code>, <code>Processable</code></td></tr><tr><td>Notifications</td><td>System notifications (model lifecycle, payments, assignments, chat, state changes)</td></tr><tr><td>Scheduled job</td><td><a href="/system-reference/backend/scheduled-jobs/chatable-scheduler"><code>ChatableScheduler</code></a></td></tr><tr><td>Service</td><td><code>BroadcastManager</code></td></tr></tbody></table><p>→ Setup, channel naming, Echo client, testing, and troubleshooting: <a href="/guide/broadcasting/overview">Broadcasting guide</a>.</p><hr><p>→ Looking for something not covered above? Browse the <a href="/system-reference/overview">system reference index</a> or jump straight into the per-section overview pages linked from each heading.</p>`,165),s=[d];function c(n,i,l,h,p,u){return r(),t("div",null,s)}const b=e(a,[["render",c]]);export{m as __pageData,b as default};
